"""The package is a native Google ADK app: ADK's loader finds it and ADK's own Runner runs it (generated by adk_v2/6.0.0)."""

from pathlib import Path

from google.adk.apps import App
from google.adk.cli.utils.agent_loader import AgentLoader
from google.adk.runners import InMemoryRunner
from google.adk.workflow import Workflow
from google.genai import types

from retail_kyc_onboarding._engine.runtime.entry import build_workflow_and_app
from retail_kyc_onboarding._engine.testing.offline import offline_providers
from retail_kyc_onboarding._engine.testing.trajectory import check_trajectory
from retail_kyc_onboarding.workflow import WORKFLOW
from retail_kyc_onboarding.settings import build_config


def test_adk_loader_finds_a_resumable_app_around_a_workflow(root: Path):
    """What `adk web`, `adk run` and `adk api_server` load: an ADK App whose root agent is an ADK Workflow."""
    loaded = AgentLoader(str(root.parent)).load_agent("retail_kyc_onboarding")
    assert isinstance(loaded, App) and isinstance(loaded.root_agent, Workflow)
    assert loaded.resumability_config is not None and loaded.resumability_config.is_resumable


async def test_adk_runner_streams_a_run_that_follows_the_graph():
    """ADK's InMemoryRunner drives the workflow itself, event by event, with no other orchestrator in between."""
    providers = offline_providers(WORKFLOW)
    _, app = await build_workflow_and_app(WORKFLOW, build_config(providers=providers))
    runner = InMemoryRunner(app=app)
    session = await runner.session_service.create_session(app_name=app.name, user_id="test-user")
    message = types.Content(role="user", parts=[types.Part(text="hello")])
    events = [e async for e in runner.run_async(user_id="test-user", session_id=session.id, new_message=message)]
    assert events and not [e.error_code for e in events if e.error_code]
    assert not check_trajectory(providers.telemetry.sink.records, WORKFLOW.graph)
